// Minimal heightmap example with 3D perspective and camera movement
// Author: ChatGPT

// Function to generate pseudo-random noise (simple approximation)
float noise(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Interpolated noise for smoother transitions
float smoothNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Four corners of the grid
    float a = noise(i);
    float b = noise(i + vec2(1.0, 0.0));
    float c = noise(i + vec2(0.0, 1.0));
    float d = noise(i + vec2(1.0, 1.0));

    // Smooth interpolation
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// Fractal noise to simulate terrain
float fractalNoise(vec2 p) {
    float value = 0.0;
    float amplitude = 1.0;
    float frequency = 1.0;

    for (int i = 0; i < 5; i++) { // 5 octaves of detail
        value += amplitude * smoothNoise(p * frequency);
        frequency *= 2.0;
        amplitude *= 0.5;
    }
    return value;
}

// Generate terrain height based on fractal noise
float getHeight(vec2 p) {
    return fractalNoise(p) * 2.0 - 1.0; // Scale height to range [-1, 1]
}

// Calculate normal for lighting
vec3 calculateNormal(vec3 p, vec2 uv, float scale) {
    float hL = getHeight(uv + vec2(-scale, 0.0));
    float hR = getHeight(uv + vec2(scale, 0.0));
    float hD = getHeight(uv + vec2(0.0, -scale));
    float hU = getHeight(uv + vec2(0.0, scale));
    return normalize(vec3(hL - hR, 2.0 * scale, hD - hU));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy * 2.0 - 1.0; // Normalize coordinates to [-1, 1]
    uv.x *= iResolution.x / iResolution.y; // Keep aspect ratio

    // Camera and perspective setup
    float time = iTime * 0.2;
    vec3 camPos = vec3(sin(time) * 5.0, 2.0, cos(time) * 5.0);
    vec3 target = vec3(0.0, 0.0, 0.0);
    vec3 up = vec3(0.0, 1.0, 0.0);

    // Camera basis vectors
    vec3 forward = normalize(target - camPos);
    vec3 right = normalize(cross(forward, up));
    vec3 cameraUp = cross(right, forward);

    // Ray direction in world space
    vec3 rayDir = normalize(forward + uv.x * right + uv.y * cameraUp);

    // Raymarching parameters
    vec3 rayPos = camPos;
    float t = 0.0;
    float height;
    bool hit = false;

    for (int i = 0; i < 128; i++) {
        vec2 pos = rayPos.xz * 0.1; // Scale down for terrain detail
        height = getHeight(pos);

        if (rayPos.y < height) {
            hit = true;
            break;
        }

        rayPos += rayDir * 0.1;
        t += 0.1;
        if (t > 50.0) break; // Avoid infinite loops
    }

    vec3 color = vec3(0.0);

    if (hit) {
        vec3 normal = calculateNormal(rayPos, rayPos.xz * 0.1, 0.01);
        vec3 lightDir = normalize(vec3(0.8, 1.0, 0.6));

        float diff = max(dot(normal, lightDir), 0.0);
        float heightFactor = smoothstep(-1.0, 1.0, rayPos.y);

        if (rayPos.y < 0.0) {
            color = vec3(0.2, 0.6, 0.2) * diff; // Grass/vegetation
        } else if (rayPos.y < 0.5) {
            color = vec3(0.5, 0.4, 0.3) * diff; // Rock
        } else {
            color = vec3(1.0, 1.0, 1.0) * diff; // Snow
        }
    }

    fragColor = vec4(color, 1.0);
}
